import java.util.*; // Java 常用集合、队列、堆与数组工具

class Solution {
    public List<List<Integer>> subsets(int[] nums) {
        List<List<Integer>> answer = new ArrayList<>();
        backtrack(nums, 0, new ArrayList<>(), answer);
        return answer;
    }

    private void backtrack(int[] nums, int start,
                           List<Integer> path, List<List<Integer>> answer) {
        // 当前 path 已是一个子集（含最初的空集），进入就拷贝。
        answer.add(new ArrayList<>(path));

        // 只从 start 往后选，下标递增，同一组元素不会换序再出现。
        for (int i = start; i < nums.length; i++) {
            path.add(nums[i]);
            backtrack(nums, i + 1, path, answer); // 下一层起点后移，不再选更小下标
            path.remove(path.size() - 1); // 撤销本题选择，改试同层下一个数
        }
    }
}

import java.util.*; // Java 常用集合、队列、堆与数组工具

class Solution {
    public List<List<Integer>> combinationSum(int[] candidates, int target) {
        Arrays.sort(candidates); // 排序后可以在 candidate > remain 时直接剪枝。
        List<List<Integer>> answer = new ArrayList<>();
        backtrack(candidates, 0, target, new ArrayList<>(), answer);
        return answer;
    }

    private void backtrack(int[] candidates, int start, int remain,
                           List<Integer> path, List<List<Integer>> answer) {
        if (remain == 0) {
            answer.add(new ArrayList<>(path)); // 当前路径的和刚好用完 target
            return;
        }

        for (int i = start; i < candidates.length; i++) {
            int value = candidates[i];
            if (value > remain) break; // 后面的数更大，也不可能再选。

            path.add(value);

            // 仍然传 i 而不是 i + 1，表示同一个候选数可以重复使用。
            backtrack(candidates, i, remain - value, path, answer);

            path.remove(path.size() - 1); // 撤销 value，改选同层下一个候选
        }
    }
}

import java.util.*;

class Solution {
    public List<List<Integer>> combinationSum2(int[] candidates, int target) {
        Arrays.sort(candidates); // 相同值挨在一起，后面才能按层去重并提前结束。
        List<List<Integer>> answer = new ArrayList<>();
        backtrack(candidates, 0, target, new ArrayList<>(), answer);
        return answer;
    }

    private void backtrack(int[] candidates, int start, int remain,
                           List<Integer> path, List<List<Integer>> answer) {
        if (remain == 0) {
            answer.add(new ArrayList<>(path));
            return;
        }

        for (int i = start; i < candidates.length; i++) {
            // 同一层只取一次这个值，避免 [1,2] 和 [2,1] 这类重复组合。
            if (i > start && candidates[i] == candidates[i - 1]) {
                continue;
            }

            int value = candidates[i];
            if (value > remain) {
                break; // 已排序，后面的数都更大，不可能再凑出 remain。
            }

            path.add(value);
            // 下一层从 i+1 开始，当前这个下标不能再选。
            backtrack(candidates, i + 1, remain - value, path, answer);
            path.remove(path.size() - 1);
        }
    }
}

import java.util.*; // Java 常用集合、队列、堆与数组工具

class Solution {
    private static final String[] MAPPING = {
            "", "", "abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"
    };

    public List<String> letterCombinations(String digits) {
        List<String> answer = new ArrayList<>();
        if (digits.isEmpty()) return answer; // 没有数字可映射

        backtrack(digits, 0, new StringBuilder(), answer);
        return answer;
    }

    private void backtrack(String digits, int index,
                           StringBuilder path, List<String> answer) {
        if (index == digits.length()) {
            answer.add(path.toString()); // 每一位都已选定一个字母
            return;
        }

        String letters = MAPPING[digits.charAt(index) - '0'];
        for (char c : letters.toCharArray()) {
            path.append(c);                  // 选择当前数字对应的一个字母。
            backtrack(digits, index + 1, path, answer);
            path.deleteCharAt(path.length() - 1); // 回溯，尝试同层下一个字母。
        }
    }
}

import java.util.*; // Java 常用集合、队列、堆与数组工具

class Solution {
    public List<List<Integer>> permute(int[] nums) {
        List<List<Integer>> answer = new ArrayList<>();
        boolean[] used = new boolean[nums.length];
        backtrack(nums, used, new ArrayList<>(), answer);
        return answer;
    }

    private void backtrack(int[] nums, boolean[] used,
                           List<Integer> path, List<List<Integer>> answer) {
        // 长度到 n，当前 path 已是一个完整排列
        if (path.size() == nums.length) {
            answer.add(new ArrayList<>(path)); // 复制一份，避免后面撤销时改掉已保存的结果
            return;
        }

        for (int i = 0; i < nums.length; i++) {
            if (used[i]) continue;

            // 占用下标 i，把这个数字放到当前层
            used[i] = true;
            path.add(nums[i]);

            backtrack(nums, used, path, answer);

            // 撤销后，同一层才能尝试下一个未使用的数字
            path.remove(path.size() - 1);
            used[i] = false;
        }
    }
}

import java.util.*;

class Solution {
    public List<List<Integer>> permuteUnique(int[] nums) {
        Arrays.sort(nums);

        List<List<Integer>> answer = new ArrayList<>();
        List<Integer> path = new ArrayList<>();
        boolean[] used = new boolean[nums.length];

        backtrack(nums, used, path, answer);
        return answer;
    }

    private void backtrack(int[] nums, boolean[] used,
                           List<Integer> path, List<List<Integer>> answer) {
        if (path.size() == nums.length) {
            answer.add(new ArrayList<>(path));
            return;
        }

        for (int i = 0; i < nums.length; i++) {
            if (used[i]) continue;

            // 前一个相同值还没在本层用过，再用当前值会得到同一条排列。
            if (i > 0 && nums[i] == nums[i - 1] && !used[i - 1]) {
                continue;
            }

            used[i] = true;
            path.add(nums[i]);

            backtrack(nums, used, path, answer);

            path.remove(path.size() - 1);
            used[i] = false;
        }
    }
}

import java.util.*;

class Solution {
    private boolean[][] palindrome;

    public List<List<String>> partition(String s) {
        int n = s.length();
        palindrome = new boolean[n][n];

        // 先预处理所有子串是否为回文。按长度递增，保证内部状态已经计算。
        for (int len = 1; len <= n; len++) {
            for (int left = 0; left + len - 1 < n; left++) {
                int right = left + len - 1;
                palindrome[left][right] = s.charAt(left) == s.charAt(right)
                        && (len <= 2 || palindrome[left + 1][right - 1]);
            }
        }

        List<List<String>> answer = new ArrayList<>();
        backtrack(s, 0, new ArrayList<>(), answer);
        return answer;
    }

    private void backtrack(String s, int start,
                           List<String> path, List<List<String>> answer) {
        if (start == s.length()) {
            answer.add(new ArrayList<>(path)); // 整串切完，记下当前方案
            return;
        }

        for (int end = start; end < s.length(); end++) {
            if (!palindrome[start][end]) continue; // 这一段不是回文，换更长的终点

            path.add(s.substring(start, end + 1));
            backtrack(s, end + 1, path, answer); // 剩余后缀从 end 的下一位接着切
            path.remove(path.size() - 1);
        }
    }
}

import java.util.ArrayList;
import java.util.List;

class Solution {
    public List<String> restoreIpAddresses(String s) {
        List<String> ans = new ArrayList<>();
        dfs(s, 0, 0, new ArrayList<>(), ans);
        return ans;
    }

    private void dfs(String s, int index, int part, List<String> path, List<String> ans) {
        if (part == 4) {
            // 四段用完且字符也用完才是完整 IP
            if (index == s.length()) {
                ans.add(String.join(".", path));
            }
            return;
        }

        int remainChars = s.length() - index;
        int remainParts = 4 - part;
        // 剩下的字符不够分，或长到每段 3 位仍放不下
        if (remainChars < remainParts || remainChars > remainParts * 3) {
            return;
        }

        for (int len = 1; len <= 3 && index + len <= s.length(); len++) {
            String seg = s.substring(index, index + len);
            // 更长仍会带前导零，不必再试
            if (seg.length() > 1 && seg.charAt(0) == '0') {
                break;
            }
            int val = Integer.parseInt(seg);
            if (val > 255) {
                break;
            }
            path.add(seg);
            dfs(s, index + len, part + 1, path, ans);
            path.remove(path.size() - 1);
        }
    }
}

import java.util.*; // 后面要用 List、ArrayList 和 Arrays。

class Solution {
    public List<List<String>> solveNQueens(int n) {
        List<List<String>> answer = new ArrayList<>();
        int[] queens = new int[n]; // 一行只放一个皇后，记下它所在的列。
        Arrays.fill(queens, -1);

        boolean[] columns = new boolean[n];
        boolean[] diag1 = new boolean[2 * n - 1]; // row-col 相同的格子落在同一条对角线上。
        boolean[] diag2 = new boolean[2 * n - 1]; // row+col 相同的格子落在另一条对角线上。

        backtrack(0, n, queens, columns, diag1, diag2, answer);
        return answer;
    }

    private void backtrack(int row, int n, int[] queens,
                           boolean[] columns, boolean[] diag1, boolean[] diag2,
                           List<List<String>> answer) {
        if (row == n) {
            answer.add(buildBoard(queens, n));
            return;
        }

        for (int col = 0; col < n; col++) {
            int d1 = row - col + n - 1;
            int d2 = row + col;

            // 列或对角线已被占用，这一列不用再进入下一行。
            if (columns[col] || diag1[d1] || diag2[d2]) continue;

            queens[row] = col;
            columns[col] = diag1[d1] = diag2[d2] = true;

            backtrack(row + 1, n, queens, columns, diag1, diag2, answer);

            // 换下一列前清掉占用，否则后续分支会把这里当成已放皇后。
            columns[col] = diag1[d1] = diag2[d2] = false;
            queens[row] = -1;
        }
    }

    private List<String> buildBoard(int[] queens, int n) {
        List<String> board = new ArrayList<>();
        for (int row = 0; row < n; row++) {
            char[] line = new char[n];
            Arrays.fill(line, '.');
            line[queens[row]] = 'Q';
            board.add(new String(line));
        }
        return board;
    }
}

import java.util.*; // Java 常用集合、队列、堆与数组工具

class Solution {
    public boolean exist(char[][] board, String word) {
        for (int r = 0; r < board.length; r++) {
            for (int c = 0; c < board[0].length; c++) {
                if (dfs(board, word, r, c, 0)) return true; // 任一起点匹配成功即可
            }
        }
        return false;
    }

    private boolean dfs(char[][] board, String word, int r, int c, int index) {
        // index 已经走到 word.length()，说明前面的字符全部匹配成功。
        if (index == word.length()) return true;

        if (r < 0 || r >= board.length || c < 0 || c >= board[0].length) return false;
        if (board[r][c] != word.charAt(index)) return false;

        char original = board[r][c];
        board[r][c] = '#'; // 临时标记当前格子，防止同一路径重复使用。

        boolean found = dfs(board, word, r + 1, c, index + 1)
                || dfs(board, word, r - 1, c, index + 1)
                || dfs(board, word, r, c + 1, index + 1)
                || dfs(board, word, r, c - 1, index + 1);

        board[r][c] = original; // 回溯：恢复现场，供其他起点/路径继续使用。
        return found;
    }
}

import java.util.*; // Java 常用集合、队列、堆与数组工具

class Solution {
    public List<String> generateParenthesis(int n) {
        List<String> answer = new ArrayList<>();
        backtrack(n, 0, 0, new StringBuilder(), answer);
        return answer;
    }

    private void backtrack(int n, int opened, int closed,
                           StringBuilder path, List<String> answer) {
        if (path.length() == 2 * n) {
            answer.add(path.toString()); // n 对都已放完
            return;
        }

        // 左括号总数不能超过 n。
        if (opened < n) {
            path.append('(');
            backtrack(n, opened + 1, closed, path, answer);
            path.deleteCharAt(path.length() - 1);
        }

        // 任何前缀中右括号数量都不能超过左括号，否则一定非法。
        if (closed < opened) {
            path.append(')');
            backtrack(n, opened, closed + 1, path, answer);
            path.deleteCharAt(path.length() - 1); // 撤销这一位，换另一种括号
        }
    }
}

class Solution {
    public List<String> removeInvalidParentheses(String s) {
        List<String> ans = new ArrayList<>();
        Set<String> visited = new HashSet<>();
        Queue<String> queue = new LinkedList<>();
        queue.offer(s);
        visited.add(s);
        boolean found = false;
        while (!queue.isEmpty()) {
            String cur = queue.poll();
            if (isValid(cur)) {
                // 同一层删除次数相同，收集本层合法串
                ans.add(cur);
                found = true;
            }
            if (found) {
                // 已有最少删除方案，不再继续删
                continue;
            }
            for (int i = 0; i < cur.length(); i++) {
                char c = cur.charAt(i);
                if (c != '(' && c != ')') {
                    continue;
                }
                // 只删一个括号，生成下一层候选
                String next = cur.substring(0, i) + cur.substring(i + 1);
                if (visited.add(next)) {
                    queue.offer(next);
                }
            }
        }
        return ans;
    }

    private boolean isValid(String s) {
        int balance = 0;
        for (char c : s.toCharArray()) {
            if (c == '(') {
                balance++;
            } else if (c == ')') {
                // 右括号更多则不合法
                if (balance == 0) {
                    return false;
                }
                balance--;
            }
        }
        return balance == 0;
    }
}

import java.util.*;

class Solution {
    public String largestLessThanN(int[] nums, String n) {
        if (nums == null || nums.length == 0 || n == null || n.isEmpty()) {
            return "-1";
        }
        // 按非负整数理解，没有任何数严格小于 0。
        if (n.equals("0")) {
            return "-1";
        }

        // 只保留 0~9，重复数字对能组成的数没有区别。
        boolean[] present = new boolean[10];
        for (int digit : nums) {
            if (digit < 0 || digit > 9) {
                throw new IllegalArgumentException("nums 中每个元素都必须是 0~9 的数字");
            }
            present[digit] = true;
        }

        int count = 0;
        for (boolean exists : present) {
            if (exists) count++;
        }

        int[] digits = new int[count];
        int index = 0;
        for (int digit = 0; digit <= 9; digit++) {
            if (present[digit]) digits[index++] = digit;
        }

        char[] target = n.toCharArray();
        char[] path = new char[target.length];

        // 位数相同才能比少一位的数更大，所以先尝试等长。
        if (buildSameLength(0, false, target, digits, path)) {
            return new String(path);
        }

        // 每一位都无法变小，只能少一位。
        int shorterLength = target.length - 1;
        if (shorterLength <= 0) {
            return present[0] ? "0" : "-1";
        }

        int largestDigit = digits[digits.length - 1];
        int largestNonZero = -1;
        for (int i = digits.length - 1; i >= 0; i--) {
            if (digits[i] != 0) {
                largestNonZero = digits[i];
                break;
            }
        }

        if (largestNonZero == -1) {
            // 可用数字只有 0，最大的合法数就是 0。
            return present[0] ? "0" : "-1";
        }

        StringBuilder answer = new StringBuilder();
        answer.append(largestNonZero);
        for (int i = 1; i < shorterLength; i++) {
            answer.append(largestDigit);
        }
        return answer.toString();
    }

    private boolean buildSameLength(int pos, boolean alreadySmaller,
                                    char[] target, int[] digits, char[] path) {
        if (pos == target.length) {
            // 和 n 完全相同不算答案。
            return alreadySmaller;
        }

        int limit = alreadySmaller ? 9 : target[pos] - '0';

        // 从大往小试，第一个能走通的就是这一位上的最大选择。
        for (int i = digits.length - 1; i >= 0; i--) {
            int digit = digits[i];
            if (digit > limit) continue;

            // 多位数不能以 0 开头，否则实际位数会变短。
            if (pos == 0 && target.length > 1 && digit == 0) continue;

            path[pos] = (char) ('0' + digit);
            boolean nextSmaller = alreadySmaller || digit < target[pos] - '0';

            if (buildSameLength(pos + 1, nextSmaller, target, digits, path)) {
                return true;
            }
        }

        return false;
    }
}
